 * Test a version against a range.
 *
 * @param {string} version Version to test.
 * @param {string} range Range to test against.
 * @returns {boolean} True when every comparator holds.
 */
export function satisfies(version, range) {
  const parsed = parseVersion(version); // Validates the version
  const comparators = parseRange(range); // Validates the range

  for (const comp of comparators) {
    const compParsed = parseVersion(comp.version);
    let holds = false;

    if (comp.operator === '=') {
      holds = parsed.major === compParsed.major &&
              parsed.minor === compParsed.minor &&
              parsed.patch === compParsed.patch;
    } else if (comp.operator === '>=') {
      const cmp = compareVersions(version, comp.version);
      holds = cmp >= 0;
    } else if (comp.operator === '>') {
      const cmp = compareVersions(version, comp.version);
      holds = cmp > 0;
    } else if (comp.operator === '<=') {
      const cmp = compareVersions(version, comp.version);
      holds = cmp <= 0;
    } else if (comp.operator === '<') {
      const cmp = compareVersions(version, comp.version);
      holds = cmp < 0;
    }

    if (!holds) return false;
  }

  return true;
}"}

