    }

    const versions = [];
    for (const [versionStr, metadata] of Object.entries(packageEntry)) {
      // Parse and validate version
      try {
        parseVersion(versionStr);
      } catch (e) {
        throw e; // Re-throw the BAD_VERSION error
      }

      // Validate metadata
      if (metadata === null || typeof metadata !== 'object' || Array.isArray(metadata)) {
        throw new ResolveError('BAD_REGISTRY', `metadata must be an object: ${name}@${versionStr}`);
      }

      // Validate dependencies if present
      if (metadata.deps !== undefined) {
        if (metadata.deps === null || typeof metadata.deps !== 'object' || Array.isArray(metadata.deps)) {
          throw new ResolveError('BAD_DEPENDENCIES', `dependencies of ${name}@${versionStr} must be an object`);
        }
        // Validate each dependency range
        for (const [depName, depRange] of Object.entries(metadata.deps)) {
          try {
            parseRange(depRange);
          } catch (e) {
            throw e; // Re-throw the BAD_RANGE error
          }
        }
      }

      versions.push(versionStr);
    }

    // Sort versions numerically
    versions.sort(compareVersions);
    registryVersions[name] = versions;
  }

  // Validate and parse all root dependency ranges
  const rootRanges = {};
  for (const [name, range] of Object.entries(rootDeps)) {
    try {
      parseRange(range);
    } catch (e) {
      throw e; // Re-throw the BAD_RANGE error
    }
    rootRanges[name] = range;
  }

  // Resolution algorithm
  const resolved = {}; // name -> version
  const order = []; // selection order
  const constraints = {}; // name -> array of {range, via}
  const pending = new Set(); // names pending selection

  // Seed from root dependencies in ascending name order
  const rootNames = Object.keys(rootRanges).sort();
  for (const name of rootNames) {
    constraints[name] = [{ range: rootRanges[name], via: '<root>' }];
    pending.add(name);
  }

